"""Vegetation indices from spectra_mean.csv generated by process_wheat_study.

Input: wavelength column and one column per sample; optionally long format
(sample, wavelength, mean_intensity).
Output: rows=samples, columns=indices, plus optional index documentation CSV.

IMPORTANT: Standard reflectance indices assume band reflectance R(lambda).
Ratios and normalized differences can also be used on proportional, *zero-offset*
intensity signals (for exploratory comparisons), if all spectral conditions
are consistent. Absolute-offset/surface-reflectance indices require R in [0,1].
"""
from pathlib import Path
import numpy as np
import pandas as pd
from index_band_interpolation import band_status, sample_band

# name: (description, formula, required wavelength centers (nm), scale-invariant)
INDEX_INFO = {
    'NDVI': ('Normalized Difference Vegetation Index', '(R800-R680)/(R800+R680)', (800,680), True),
    'NDVI_670': ('NDVI 800/670 variant', '(R800-R670)/(R800+R670)', (800,670), True),
    'GNDVI': ('Green Normalized Difference Vegetation Index', '(R800-R550)/(R800+R550)', (800,550), True),
    'NDRE': ('Normalized Difference Red Edge', '(R790-R720)/(R790+R720)', (790,720), True),
    'NDVI705': ('Red-edge normalized difference', '(R750-R705)/(R750+R705)', (750,705), True),
    'CIgreen': ('Green Chlorophyll Index', 'R790/R550-1', (790,550), True),
    'CIrededge': ('Red-edge Chlorophyll Index', 'R790/R710-1', (790,710), True),
    'SR': ('Simple Ratio (NIR/red)', 'R800/R680', (800,680), True),
    'SR705': ('Simple Ratio red-edge', 'R750/R710', (750,710), True),
    'VOG1': ('Vogelmann Red-edge Index 1', 'R740/R720', (740,720), True),
    'MTCI': ('MERIS Terrestrial Chlorophyll Index (750/710/680 variant)', '(R750-R710)/(R710-R680)', (750,710,680), True),
    'PRI': ('Photochemical Reflectance Index', '(R531-R570)/(R531+R570)', (531,570), True),
    'PRI570_530': ('PRI on 10-nm grid, approximate 530 for 531', '(R530-R570)/(R530+R570)', (530,570), True),
    'PSRI': ('Plant Senescence Reflectance Index', '(R680-R500)/R750', (680,500,750), True),
    'SIPI': ('Structure Insensitive Pigment Index', '(R800-R445)/(R800-R680)', (800,445,680), True),
    'ARI1': ('Anthocyanin Reflectance Index 1', '1/R550-1/R700', (550,700), False),
    'ARI2': ('Anthocyanin Reflectance Index 2', 'R800*(1/R550-1/R700)', (550,700,800), True),
    'CRI1': ('Carotenoid Reflectance Index 1', '1/R510-1/R550', (510,550), False),
    'CRI2': ('Carotenoid Reflectance Index 2', '1/R510-1/R700', (510,700), False),
    'WBI': ('Water Band Index', 'R900/R970', (900,970), True),
    'NRI': ('Nitrogen Reflectance Index (570,670)', '(R570-R670)/(R570+R670)', (570,670), True),
    'RGI': ('Red-Green Index', 'R690/R550', (690,550), True),
    'R750_R700': ('Red-edge chlorophyll ratio', 'R750/R700', (750,700), True),
    'mND705': ('Modified ND705', '(R750-R705)/(R750+R705-2*R445)', (750,705,445), True),
    'MSR705': ('Modified simple ratio 705', '(R750-R445)/(R705-R445)', (750,445,705), True),
    'REP': ('Red Edge Position, linear four-band estimate (nm)', '700+40*((R670+R780)/2-R700)/(R740-R700)', (670,780,700,740), False),
    'MCARI': ('Modified Chlorophyll Absorption Ratio Index', '((R700-R670)-0.2*(R700-R550))*(R700/R670)', (700,670,550), False),
    'TCARI': ('Transformed Chlorophyll Absorption Ratio Index', '3*((R700-R670)-0.2*(R700-R550)*(R700/R670))', (700,670,550), False),
    'TVI': ('Triangular Vegetation Index', '0.5*(120*(R750-R550)-200*(R670-R550))', (750,550,670), False),
    'DVI': ('Difference Vegetation Index', 'R800-R680', (800,680), False),
    'RDVI': ('Renormalized Difference Vegetation Index', '(R800-R670)/sqrt(R800+R670)', (800,670), False),
    'OSAVI': ('Optimized Soil Adjusted Vegetation Index', '1.16*(R800-R670)/(R800+R670+0.16)', (800,670), False),
    'SAVI': ('Soil Adjusted Vegetation Index (L=0.5)', '1.5*(R800-R680)/(R800+R680+0.5)', (800,680), False),
    'EVI': ('Enhanced Vegetation Index', '2.5*(R800-R680)/(R800+6*R680-7.5*R450+1)', (800,680,450), False),
    'MSAVI': ('Modified Soil Adjusted Vegetation Index', '(2*R800+1-sqrt((2*R800+1)^2-8*(R800-R670)))/2', (800,670), False),
    'MCARI_OSAVI': ('MCARI divided by OSAVI', 'MCARI/OSAVI', (700,670,550,800), False),
    'TCARI_OSAVI': ('TCARI divided by OSAVI', 'TCARI/OSAVI', (700,670,550,800), False),
}


def _div(a, b):
    with np.errstate(divide='ignore', invalid='ignore', over='ignore'):
        return np.where(np.abs(b) > 1e-12, a / b, np.nan)


def _read_spectra(path):
    df = pd.read_csv(path)
    if {'sample', 'wavelength', 'mean_intensity'}.issubset(df.columns):
        if df.duplicated(['sample', 'wavelength']).any():
            raise ValueError('Duplicate sample/wavelength rows in long input')
        df = df.pivot(index='wavelength', columns='sample', values='mean_intensity')
    else:
        if 'wavelength' not in df.columns:
            raise ValueError('Expected wavelength column (spectra_mean.csv or spectra_long.csv)')
        df = df.set_index('wavelength')
    df.index = pd.to_numeric(df.index, errors='raise')
    if not df.index.is_unique:
        raise ValueError('Duplicate wavelengths')
    df = df.sort_index().apply(pd.to_numeric, errors='raise')
    if df.empty or not df.columns.size:
        raise ValueError('No sample spectra found')
    return df


def calculate_vegetation_indices(
    spectra_csv,
    output_csv='vegetation_indices.csv',
    metadata_csv=None,
    data_type='signal',
    interpolate=True,
    allow_extrapolation=False,
):
    """Calculate vegetation indices for all samples in spectra CSV.

    Parameters
    ----------
    spectra_csv : path
        Wide spectra_mean.csv (wavelength, sample1, sample2...) or
        spectra_long.csv (sample, wavelength, mean_intensity, ...).
    output_csv : path or None
        Output with one row per sample and index columns.
    metadata_csv : path or None
        Optional CSV with index definitions and scale requirements.
    data_type : {'signal','signal_exploratory','reflectance'}
        'signal': use only dimensionless, scale-invariant indices (plus REP,
        which is invariant to multiplication; not to offset). All others NaN.
        'reflectance': input values must be valid reflectance fractions [0,1]
        and all supported indices are computed.
        'signal_exploratory': calculate ALL formulas on raw signal values,
        even when their numerical results are not physically interpretable
        as established reflectance indices. For exploration only.
    interpolate : bool
        For requested centers such as 531/705/445 interpolate linearly between
        adjacent sampled wavelengths; does not reconstruct narrow-band response.
    allow_extrapolation : bool
        For safety defaults to False; requested wavelengths beyond observed
        range yield NaN.

    Returns
    -------
    pandas.DataFrame: rows=samples; columns=indices, with 'sample' column.
    """
    if data_type not in ('signal','signal_exploratory','reflectance'):
        raise ValueError("data_type must be 'signal', 'signal_exploratory' or 'reflectance'")
    if data_type == 'signal_exploratory':
        import warnings
        warnings.warn(
            'Exploratory mode: indices requiring reflectance or absolute signal scale '
            'are calculated numerically from DN; interpret them with caution. '
            'Indices with +0.16, +0.5, +1 constants in particular are NOT '
            'physically valid reflectance indices on raw DN.',
            UserWarning, stacklevel=2)

    df = _read_spectra(spectra_csv)
    w = df.index.to_numpy(dtype=float)
    raw = df.to_numpy(dtype=float)
    if data_type == 'reflectance':
        finite = raw[np.isfinite(raw)]
        if finite.size and finite.min() < 0:
            raise ValueError('Reflectance mode expects non-negative spectral ratios; check calibration.')
        # Apparent relative reflectance can exceed 1 due to noise/illumination geometry.
        # Do not silently clip it: quantitative mode is an explicit user choice.

    if allow_extrapolation:
        raise ValueError('Index calculation never extrapolates beyond measured wavelengths')

    def R(nm):
        return sample_band(w, raw, nm, axis=0, interpolate=interpolate)

    r = {v: R(v) for entry in INDEX_INFO.values() for v in entry[2]}
    def x(n): return r[n]
    def nd(a,b): return _div(x(a)-x(b),x(a)+x(b))
    with np.errstate(divide='ignore', invalid='ignore', over='ignore'):
        mcari = ((x(700)-x(670))-0.2*(x(700)-x(550)))*_div(x(700),x(670))
        tcari = 3*((x(700)-x(670))-0.2*(x(700)-x(550))*_div(x(700),x(670)))
        osavi = _div(1.16*(x(800)-x(670)), x(800)+x(670)+0.16)
        radicand = (2*x(800)+1)**2-8*(x(800)-x(670))
        values = {
            'NDVI': nd(800,680), 'NDVI_670': nd(800,670),
            'GNDVI': nd(800,550), 'NDRE': nd(790,720), 'NDVI705': nd(750,705),
            'CIgreen': _div(x(790),x(550))-1,
            'CIrededge': _div(x(790),x(710))-1,
            'SR': _div(x(800),x(680)), 'SR705': _div(x(750),x(710)),
            'VOG1': _div(x(740),x(720)),
            'MTCI': _div(x(750)-x(710),x(710)-x(680)),
            'PRI': nd(531,570), 'PRI570_530': nd(530,570),
            'PSRI': _div(x(680)-x(500),x(750)),
            'SIPI': _div(x(800)-x(445),x(800)-x(680)),
            'ARI1': _div(1,x(550))-_div(1,x(700)),
            'ARI2': x(800)*(_div(1,x(550))-_div(1,x(700))),
            'CRI1': _div(1,x(510))-_div(1,x(550)),
            'CRI2': _div(1,x(510))-_div(1,x(700)),
            'WBI': _div(x(900),x(970)),
            'NRI': nd(570,670), 'RGI': _div(x(690),x(550)),
            'R750_R700': _div(x(750),x(700)),
            'mND705': _div(x(750)-x(705), x(750)+x(705)-2*x(445)),
            'MSR705': _div(x(750)-x(445),x(705)-x(445)),
            'REP': 700+40*_div((x(670)+x(780))/2-x(700),x(740)-x(700)),
            'MCARI': mcari, 'TCARI': tcari,
            'TVI': 0.5*(120*(x(750)-x(550))-200*(x(670)-x(550))),
            'DVI': x(800)-x(680),
            'RDVI': _div(x(800)-x(670),np.sqrt(np.maximum(x(800)+x(670),0))),
            'OSAVI': osavi,
            'SAVI': _div(1.5*(x(800)-x(680)),x(800)+x(680)+0.5),
            'EVI': _div(2.5*(x(800)-x(680)),x(800)+6*x(680)-7.5*x(450)+1),
            'MSAVI': (2*x(800)+1-np.sqrt(np.where(radicand>=0,radicand,np.nan)))/2,
            'MCARI_OSAVI': _div(mcari,osavi),
            'TCARI_OSAVI': _div(tcari,osavi),
        }

    # REP (a wavelength, nm) and ARI2 remain invariant under multiplicative
    # scaling, whereas ARI1 and CRI1/2 do not.
    signal_ok = set(k for k, v in INDEX_INFO.items() if v[3]) | {'REP'}
    if data_type == 'signal':
        for name in values:
            if name not in signal_ok:
                values[name] = np.full(raw.shape[1], np.nan)

    for key, arr in values.items():
        values[key] = np.where(np.isfinite(arr), arr, np.nan)
    # Each index gets an explicit flag (one boolean per sample).
    # Missing/excluded indices still carry the correct spectral availability flag.
    flags = {}
    status_by_name = {}
    for name, entry in INDEX_INFO.items():
        status, interpolated_nm, missing_nm = band_status(w, entry[2], interpolate=interpolate)
        status_by_name[name] = (status, interpolated_nm, missing_nm)
        if missing_nm:
            values[name] = np.full(raw.shape[1], np.nan)
        flags[name + '_interpolated'] = [bool(interpolated_nm) if not missing_nm else False] * raw.shape[1]
    columns = {'sample': [str(c) for c in df.columns]}
    for name in INDEX_INFO:
        columns[name] = values[name]
        columns[name + '_interpolated'] = flags[name + '_interpolated']
    result = pd.DataFrame(columns)

    if output_csv is not None:
        out = Path(output_csv)
        out.parent.mkdir(parents=True, exist_ok=True)
        result.to_csv(out, index=False, na_rep='NA')
    if metadata_csv is not None:
        meta = pd.DataFrame([
            {'index': name, 'description': entry[0], 'formula': entry[1],
             'wavelengths_nm': ','.join(map(str,entry[2])),
             'available_with_signal': name in signal_ok,
             'requires_reflectance_0_1': name in {'OSAVI','SAVI','EVI','MSAVI','MCARI_OSAVI','TCARI_OSAVI'},
             'data_type_mode': data_type,
             'calculation_status': ('calculated' if result[name].notna().any() else
                  'excluded_by_signal_mode' if data_type == 'signal' and name not in signal_ok else
                  'undefined_or_missing_input'),
             'caution': ('' if name in signal_ok else
                   'Reflectance-scale constants: DN calculation not physically valid'
                   if name in {'OSAVI','SAVI','EVI','MSAVI','MCARI_OSAVI','TCARI_OSAVI'} else
                   'Depends on absolute signal scale; DN result is not a calibrated reflectance index'),
             'interpolated_wavelengths_nm': ','.join(str(t) for t in status_by_name[name][1]),
             'missing_wavelengths_nm': ','.join(str(t) for t in status_by_name[name][2]),
             'wavelength_status': status_by_name[name][0]}
            for name, entry in INDEX_INFO.items()
        ])
        out = Path(metadata_csv)
        out.parent.mkdir(parents=True, exist_ok=True)
        meta.to_csv(out,index=False)
    return result


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('spectra_csv')
    parser.add_argument('--output', default='vegetation_indices.csv')
    parser.add_argument('--metadata', default='vegetation_indices_descriptions.csv')
    parser.add_argument('--data-type', choices=['signal', 'signal_exploratory', 'reflectance'], default='signal')
    args = parser.parse_args()
    print(calculate_vegetation_indices(args.spectra_csv,args.output,args.metadata,args.data_type).head())
